def check_occurences(tuples_list):
    # Dictionary to store the counts of normalized tuples
    counts = {}

    for tpl in tuples_list:
        # Normalize the tuple by sorting its elements
        normalized_tpl = tuple(sorted(tpl))

        # Update the count in the dictionary
        if normalized_tpl in counts:
            counts[normalized_tpl] += 1
        else:
            counts[normalized_tpl] = 1

    return counts
