import string

def find_adverb_position(sentence):
    def clean_word(word):
        # Remove punctuation from both ends of a word
        return word.strip(string.punctuation)

    words = sentence.split()
    current_index = 0  # Tracks the index of each word in the original sentence
    for word in words:
        cleaned = clean_word(word)
        if cleaned.endswith("ly"):
            # Find the first occurrence of the cleaned word within the sentence
            start_index = sentence.find(cleaned, current_index)
            end_index = start_index + len(cleaned) - 1
            return (start_index, end_index, cleaned)
        current_index += len(word) + 1  # Increment by word length + 1 (for the space)

    return None
