def remove_uppercase(s: str) -> str:
    result = []
    inside_uppercase = False  # Flag to track if we're inside an uppercase substring

    for char in s:
        if char.isupper():
            inside_uppercase = True  # Start or continue an uppercase substring
        else:
            if inside_uppercase:
                inside_uppercase = False  # We've exited an uppercase substring
            result.append(char)  # Add the non-uppercase character to the result

    return ''.join(result)
