def nth_polite_number(n):
    def is_power_of_two(x):
        return (x & (x - 1)) == 0 and x != 0

    count = 0
    num = 1

    while True:
        if not is_power_of_two(num):
            count += 1
            if count == n:
                return num
        num += 1

